"OLAYLAR_DUNYA_AVRUPA_MO:-0593-01-01:0":{"b": ["Solonun arxonluğu və seisaxtheia islahatları", "705d0dbf"], "d": ["Borc köləliyini ləğv edən islahatlar; vətəndaş sinifləri yenidən nizamlandı.", "6d544b32"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0594-01-01:0":{"b": ["Birinci Müqəddəs Müharibə: Kirrha dağıdıldı, Delfi Amfiktiyoniya nəzarətinə keçdi", "e01a15f5"], "d": ["Delfiyə giriş üçün Kirrha məhv edildi.", "1ad355f7"]},
