"OLAYLAR_DUNYA_AVRUPA_MO:-0656-01-01:0":{"b": ["Kypselos Korinfdə tiranlığı qurdu, Bakxiadailər devrildi", "f4f32246"], "d": ["Kypselos Bakxiadailər oliqarxiyasını devirib uzunmüddətli tiranlıq qurdu.", "790b64e0"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0668-01-01:0":{"b": ["Hysiai döyüşü: Arqos Pheidon rəhbərliyi altında Spartanı məğlub etdi", "47a0d03b"], "d": ["Arqosun Pheidon dövrü üstünlüyü (tarix və tarixilik mübahisəlidir).", "c3d09b3d"]},
