"OLAYLAR_DUNYA_AVRUPA_MO:-0733-01-01:0":{"b": ["Naksos (Siciliya) quruldu: Siciliyanın ilk Yunan koloniyası", "4850886a"], "d": ["Thouklesin rəhbərliyi ilə xalkislilər şərqi Siciliyada ilk Yunan koloniyasını qurdu.", "407aaab5"]},
